<div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2>Mis créditos</h2><p class="text-muted mb-0">Consulta el saldo y las cuotas de tus compras a crédito.</p></div></div>
<?php if (!empty($creditos)): ?><div class="table-responsive bg-white rounded shadow-sm"><table class="table align-middle mb-0"><thead><tr><th>Crédito</th><th>Pedido</th><th>Fecha</th><th>Total</th><th>Abonado</th><th>Saldo</th><th></th></tr></thead><tbody><?php foreach ($creditos as $credito): ?><tr><td>#<?= (int) $credito->id_credito ?></td><td>#<?= (int) $credito->id_pedido ?></td><td><?= date('d/m/Y', strtotime($credito->fecha)) ?></td><td>$<?= number_format($credito->monto_total, 0, ',', '.') ?></td><td>$<?= number_format($credito->total_abonado, 0, ',', '.') ?></td><td class="fw-bold">$<?= number_format($credito->saldo_pendiente, 0, ',', '.') ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('cliente/creditos/detalle/'.$credito->id_credito) ?>">Ver detalle</a></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><div class="alert alert-info">No tienes créditos registrados.</div><?php endif ?></div>
